import{_ as t,l as s,o as e,c as n,v as l,p as i,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"栈溢出到 shellcode","description":"","frontmatter":{"title":"栈溢出到 shellcode","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-smashing-shellcode.md","filePath":"cs/stack-smashing-shellcode.md","lastUpdated":1789023840000}'),p={name:"cs/stack-smashing-shellcode.md"};function E(m,a,A,_,B,u){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="栈溢出到-shellcode" tabindex="-1">栈溢出到 shellcode <a class="header-anchor" href="#栈溢出到-shellcode" aria-label="Permalink to &quot;栈溢出到 shellcode&quot;">​</a></h1><div class="epigraph"><p>返回地址也是栈上的数据。写过边界的字节若覆盖了它，CPU 就会跳到源码从未写过的地方。这是控制流完整性的开口，不是又一种密码分析。</p><footer>—— Aleph One, Smashing the Stack for Fun and Profit, Phrack 49, 1996；对照 Cowan 等对 canary 的后续</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/needham-schroeder-lowe">Needham–Schroeder</a>假设进程按规范走。缺口是<strong>实现把控制数据与普通对象放在同一可写栈上</strong>。本课只说明机制与为何出现 NX/canary，不提供可运行载荷或注入步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 的数组与 <code>gets</code> 一类接口不携带长度。局部缓冲之后是保存的帧指针与返回地址。越界写一旦到达返回地址，函数返回就离开编译器安排的图。历史叙述里这曾被用来把处理器引向注入的字节——今日有 NX 等缓解，本课不教如何做。</p><h3 id="课程边界" tabindex="-1">课程边界 <a class="header-anchor" href="#课程边界" aria-label="Permalink to &quot;课程边界&quot;">​</a></h3><p>禁止 shellcode、禁止复现步骤。需要的只是：空间安全失败 ⇒ 控制流不再等于源码。防御在后课层层加。</p><p><span class="marginnote">Aleph One 是历史文献，本课当反例引用，不当实验指导。Anderson 把这类失败归为实现与语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画栈帧槽位：局部变量、控制数据。指出语言与编译器可插入界检查或把返回地址移走（后课影子栈）。对照：协议逻辑再对，这一个写仍能接管进程。</p>',12)),(e(),i(c,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUF%5B%22%E5%8F%AF%E5%86%99%E7%BC%93%E5%86%B2%22%5D%20--%3E%20OOB%5B%22%E8%B6%8A%E7%95%8C%E5%86%99%22%5D%0A%20%20OOB%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%E8%A2%AB%E6%94%B9%22%5D%0A%20%20RET%20--%3E%20CF%5B%22%E6%8E%A7%E5%88%B6%E6%B5%81%E7%A6%BB%E5%BC%80%E6%BA%90%E7%A0%81%22%5D%0A%20%20NX%5B%22%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%A0%88%22%5D%20-.-%3E%7C%22%E7%BC%93%E8%A7%A3%2C%20%E9%9D%9E%E6%A0%B9%E9%99%A4%22%7C%20CF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>进程作为 TCB 的一部分：用户输入变成了跳转目标。下一课 canary：用秘密值检测「帧被踏过」，不修复语言。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给任何 payload。canary 下一课是第一道常见编译器缓解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>协议正确仍可能被内存破坏接管。</li><li>返回地址与数据同栈，越界写破坏控制流。</li><li>不提供注入方法；NX 等是缓解。</li><li>下一课栈 canary。</li><li>出处：Aleph One, Phrack 49（历史）；Anderson, <em>Security Engineering</em>；对照 Cowan et al.。</li></ul>',8))])}const k=t(p,[["render",E]]);export{C as __pageData,k as default};
